import bisect

def sort_array(array):
    """
    Given an array of non-negative integers, return a copy of the given array after sorting,
    you will sort the given array in ascending order if the sum( first index value, last index value) is odd,
    or sort it in descending order if the sum( first index value, last index value) is even.

    Note:
    * don't change the given array.

    Examples:
    * sort_array([]) => []
    * sort_array([5]) => [5]
    * sort_array([2, 4, 3, 0, 1, 5]) => [0, 1, 2, 3, 4, 5]
    * sort_array([2, 4, 3, 0, 1, 5, 6]) => [6, 5, 4, 3, 2, 1, 0]
    """
    def sum_of_first_and_last(arr):
        return sum(arr[:2])

    def sort_descending(arr):
        return sorted(arr, reverse=True)

    if not array:
        return []

    sorted_array = []
    sorted_count = 0

    for i in range(1, len(array)):
        first_index, last_index = bisect.bisect_left(array, array[i], 0, i)
        sorted_count += 1
        if sorted_count % 2 == 0:
            if (sum_of_first_and_last(array[:first_index]) + sum_of_first_and_last(array[first_index:last_index])) % 2 == 0:
                sorted_array.append(array[i])
        else:
            if (sum_of_first_and_last(array[:first_index]) + sum_of_first_and_last(array[first_index:last_index])) % 2 == 1:
                sorted_array.append(array[i])

    return sorted_array
