import math

def closest_integer(value):
    '''
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples
    >>> closest_integer("10")
    10
    >>> closest_integer("15.3")
    15

    Note:
    Rounding away from zero means that if the given number is equidistant
    from two integers, the one you should return is the one that is the
    farthest from zero. For example closest_integer("14.5") should
    return 15 and closest_integer("-14.5") should return -15.
    '''
    # Check if the number is negative
    if value[0] == '-':
        value = value[1:]
        # Handle negative numbers
        if value[-1] == '.':
            value = value[:-1]
        elif value[-2] == '.':
            value = value[:-2]
        else:
            value = value[:-1]
        # Check if the number is an integer
        if value == value[0].isdigit():
            return int(value)
        else:
            # Check if the number is positive
            if int(value) >= 0:
                return int(value)
            else:
                # Calculate the absolute value
                abs_value = abs(float(value))
                # Round away from zero
                return math.floor(abs_value) + 1 if abs_value - int(abs_value) >= 0.5 else math.ceil(abs_value) - 1
    # Check if the number is positive
    else:
        value = value[1:]
        # Handle positive numbers
        if value[-1] == '.':
            value = value[:-1]
        elif value[-2] == '.':
            value = value[:-2]
        else:
            value = value[:-1]
        # Check if the number is an integer
        if value == value[0].isdigit():
            return int(value)
        else:
            # Check if the number is negative
            if int(value) <= 0:
                return int(value)
            else:
                # Calculate the absolute value
                abs_value = abs(float(value))
                # Round away from zero
                return math.ceil(abs_value) - 1 if abs_value - int(abs_value) >= 0.5 else math.floor(abs_value) + 1

# Test cases
print(closest_integer("10"))  # Expected output: 10
print(closest_integer("15.3"))  # Expected output: 15
print(closest_integer("-14.5"))  # Expected output: -15
print(closest_integer("3.14"))  # Expected output: 3
print(closest_integer("-3.14"))  # Expected output: -3
print(closest_integer("2.14"))  # Expected output: 2
