def move_one_ball(arr):
    # Check if the array is empty
    if not arr:
        return True

    # Check if the array has only one element
    if len(arr) == 1:
        return True

    # Check if the first element is greater than the last element
    if arr[0] > arr[-1]:
        return False

    # Check if the array can be sorted by performing right shifts
    for i in range(1, len(arr) - 1):
        if arr[i] > arr[i + 1]:
            # Perform the right shift operation
            arr[i], arr[i + 1] = arr[i + 1], arr[i]
            # Check if the array is sorted by performing right shifts
            return move_one_ball(arr)

    # If no right shift operation can be performed, the array is not sorted
    return False
