def largest_smallest_integers(lst):
    if not lst:
        return (None, None)

    negative_integers = [x for x in lst if x < 0]
    positive_integers = [x for x in lst if x >= 0]

    if not negative_integers and not positive_integers:
        return (None, None)

    if not negative_integers:
        return (min(positive_integers), max(positive_integers))

    if not positive_integers:
        return (min(negative_integers), max(negative_integers))

    return (min(negative_integers), max(positive_integers))

