def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    # Check if n is even
    if n % 2 == 0:
        # Calculate the sum of 4 positive even numbers
        sum_of_evens = 4 * 2
        # Check if the sum of 4 positive even numbers equals n
        if n == sum_of_evens:
            return True
        else:
            return False
    else:
        return False
